```ts
import type { OpenClawPluginApi } from "openclaw/plugin-sdk/plugin-entry";

export default {
  id: "gateway-return-proof",
  name: "Gateway return proof",
  register(api: OpenClawPluginApi) {
    const options: NonNullable<Parameters<OpenClawPluginApi["registerGatewayMethod"]>[2]> = {
      scope: "operator.read", profileAccess: "independent",
    };
    api.registerGatewayMethod("return-proof.async", async () => ({ ok: true, status: "ready" }), options);
    api.registerGatewayMethod("return-proof.sync", () => ({ status: "synchronous" }), options);
    api.registerGatewayMethod("return-proof.false", async () => false, options);
    api.registerGatewayMethod("return-proof.null", async () => null, options);
    api.registerGatewayMethod("return-proof.callback", ({ respond }) => {
      respond(true, { status: "callback" });
    }, options);
    api.registerGatewayMethod("return-proof.async-callback", async ({ respond }) => {
      await Promise.resolve();
      respond(true, { status: "async-callback" });
    }, options);
    api.registerGatewayMethod("return-proof.precedence", async ({ respond }) => {
      respond(true, { status: "responded" });
      return { status: "ignored" };
    }, options);
    api.registerGatewayMethod("return-proof.error", async ({ respond }) => {
      respond(false, undefined, { code: "INVALID_REQUEST", message: "Explicit fixture error" });
      return { status: "ignored" };
    }, options);
  },
};
```

