```ts
import { execFileSync } from "node:child_process";
import { createServer } from "node:http";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { formatErrorMessage } from "openclaw/plugin-sdk/error-runtime";
import {
  createEmptyPluginRegistry,
  setActivePluginRegistry,
} from "openclaw/plugin-sdk/plugin-test-runtime";
import { synthesizeSpeech } from "openclaw/plugin-sdk/tts-runtime";
import { buildElevenLabsSpeechProvider } from "./extensions/elevenlabs/speech-provider-factory.ts";

const text = "Please pronounce OpenClaw and ElevenLabs.";
const locators = [
  { pronunciationDictionaryId: "dict-first", versionId: "version-a" },
  { pronunciationDictionaryId: "dict-second", versionId: "version-b" },
];
const expectedWireLocators = locators.map((locator) => ({
  pronunciation_dictionary_id: locator.pronunciationDictionaryId,
  version_id: locator.versionId,
}));
const received = [];
const server = createServer((request, response) => {
  let raw = "";
  request.setEncoding("utf8");
  request.on("data", (chunk) => { raw += chunk; });
  request.on("end", () => {
    try {
      received.push({ path: request.url, body: JSON.parse(raw) });
      response.writeHead(200, { "content-type": "audio/mpeg" });
      response.end(Buffer.from([0x49, 0x44, 0x33]));
    } catch {
      response.writeHead(400);
      response.end();
    }
  });
});

await new Promise((resolve, reject) => {
  server.once("error", reject);
  server.listen(0, "127.0.0.1", resolve);
});

const registry = createEmptyPluginRegistry();
registry.speechProviders.push({
  pluginId: "elevenlabs",
  source: "elevenlabs-production-runtime-proof",
  provider: buildElevenLabsSpeechProvider({ formatErrorMessage }),
});
setActivePluginRegistry(registry);

const home = await mkdtemp(path.join(tmpdir(), "openclaw-elevenlabs-proof-"));
const prefsPath = path.join(home, "tts-prefs.json");
const address = server.address();
if (!address || typeof address === "string") throw new Error("loopback listener did not bind");

function config(pronunciationDictionaryLocators) {
  return {
    tts: {
      auto: "always",
      provider: "elevenlabs",
      providers: {
        elevenlabs: {
          apiKey: "loopback-only-placeholder",
          baseUrl: `http://127.0.0.1:${address.port}`,
          voiceId: "abcdefghij",
          modelId: "eleven_multilingual_v2",
          ...(pronunciationDictionaryLocators === undefined
            ? {}
            : { pronunciationDictionaryLocators }),
        },
      },
    },
  };
}

try {
  const result = await synthesizeSpeech({
    text,
    cfg: config(locators),
    prefsPath,
    disableFallback: true,
  });
  const positiveControl = received[0];
  if (!positiveControl) throw new Error("TTS runtime did not reach the loopback endpoint");

  await synthesizeSpeech({
    text,
    cfg: config([]),
    prefsPath,
    disableFallback: true,
  });
  const emptyListControl = received[1];

  const beforeOversized = received.length;
  const oversizedResult = await synthesizeSpeech({
    text,
    cfg: config(Array.from({ length: 4 }, (_, index) => ({
      pronunciationDictionaryId: `dict-${index}`,
      versionId: `version-${index}`,
    }))),
    prefsPath,
    disableFallback: true,
  });

  const mode = process.env.PROOF_MODE ?? "head";
  const expectedBehaviorMatches = mode === "base"
    ? positiveControl.body.pronunciation_dictionary_locators === undefined
      && oversizedResult.success
      && received.length === beforeOversized + 1
    : JSON.stringify(positiveControl.body.pronunciation_dictionary_locators)
        === JSON.stringify(expectedWireLocators)
      && !oversizedResult.success
      && beforeOversized === received.length;
  const output = {
    headSha: execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim(),
    mode,
    entrypoint: "synthesizeSpeech public TTS runtime -> registered ElevenLabs provider -> loopback HTTP",
    bufferedAudioBytes: result.audioBuffer?.byteLength ?? 0,
    positiveControl: {
      path: positiveControl.path,
      text: positiveControl.body.text,
      locators: positiveControl.body.pronunciation_dictionary_locators ?? null,
    },
    emptyListControl: {
      locators: emptyListControl?.body.pronunciation_dictionary_locators ?? null,
    },
    oversizedControl: {
      success: oversizedResult.success,
      requestsBefore: beforeOversized,
      requestsAfter: received.length,
    },
    expectedBehaviorMatches,
    locatorsMatch: JSON.stringify(positiveControl.body.pronunciation_dictionary_locators)
      === JSON.stringify(expectedWireLocators),
    inputPreserved: positiveControl.body.text === text && emptyListControl?.body.text === text,
    emptyListOmitted: emptyListControl?.body.pronunciation_dictionary_locators === undefined,
    oversizedRejectedBeforeRequest: !oversizedResult.success && beforeOversized === received.length,
    liveVendorRequest: false,
  };
  console.log(JSON.stringify(output));
  if (
    !output.bufferedAudioBytes ||
    !output.inputPreserved ||
    !output.emptyListOmitted ||
    !output.expectedBehaviorMatches
  ) process.exitCode = 1;
} finally {
  setActivePluginRegistry(createEmptyPluginRegistry());
  await new Promise((resolve) => server.close(resolve));
  await rm(home, { recursive: true, force: true });
}
```

