export default {
  id: "proof-policy",
  name: "Proof Policy",
  description: "Blocks read calls on paths containing 'blocked' (proof only)",
  register(api) {
    api.on("before_tool_call", async (event) => {
      const path = typeof event.params?.path === "string" ? event.params.path : "";
      if (event.toolName === "read" && path.includes("blocked")) {
        return { block: true, blockReason: "proof policy denies this path" };
      }
      return undefined;
    });
