```js
// Scripted OpenAI Responses endpoint (SSE), same wire shape as the repo's gateway mock.
// The user prompt "PROOF read <path>" makes the model call read({path}); once the
// function_call_output is present it answers "done".
import http from "node:http";
const port = Number(process.argv[2] ?? 28800);
const sse = (res, events) => {
  res.writeHead(200, { "content-type": "text/event-stream" });
  res.end(events.map((e) => `data: ${JSON.stringify(e)}\n\n`).join("") + "data: [DONE]\n\n");
};
const lastUserText = (input) => {
  for (let i = input.length - 1; i >= 0; i--) {
    const it = input[i];
    if (it?.role !== "user") continue;
    const c = Array.isArray(it.content) ? it.content : [{ type: "input_text", text: String(it.content ?? "") }];
    const t = c.filter((x) => typeof x?.text === "string").map((x) => x.text).join("\n");
    if (t) return t;
  }
  return "";
};
const completed = { type: "response.completed", response: { status: "completed", usage: { input_tokens: 10, output_tokens: 10, total_tokens: 20 } } };
let n = 0;

http.createServer((req, res) => {
  let raw = "";
  req.on("data", (d) => (raw += d));
  req.on("end", () => {
    if (!req.url.endsWith("/responses")) { res.writeHead(404).end(); return; }
    const body = raw ? JSON.parse(raw) : {};
    const input = Array.isArray(body.input) ? body.input : [];
    // Last user message carrying a PROOF instruction; only items after it belong to this turn.
    const textOf = (it) => (Array.isArray(it?.content) ? it.content : []).map((x) => x?.text ?? "").join("\n");
    let at = -1;
    for (let i = input.length - 1; i >= 0; i--) if (input[i]?.role === "user" && /PROOF read \S+/.test(textOf(input[i]))) { at = i; break; }
    const m = at >= 0 ? /PROOF read (\S+)/.exec(textOf(input[at])) : null;
    const hasOutput = input.slice(at + 1).some((x) => x?.type === "function_call_output");
    n++;
    console.log(`[mock] request ${n}: ${hasOutput ? "tool output -> final" : m ? `call read ${m[1]}` : "plain"}`);
    if (!hasOutput && m) {
      const item = { type: "function_call", id: `fc_${n}`, call_id: `call_${n}`, name: "read" };
      const args = JSON.stringify({ path: m[1] });
      return sse(res, [
        { type: "response.output_item.added", item: { ...item, arguments: "" } },
        { type: "response.function_call_arguments.delta", delta: args },
        { type: "response.output_item.done", item: { ...item, arguments: args } },
        completed,
      ]);
    }
    const msg = { type: "message", id: `msg_${n}`, role: "assistant" };
    sse(res, [
      { type: "response.output_item.added", item: { ...msg, content: [], status: "in_progress" } },
      { type: "response.output_item.done", item: { ...msg, status: "completed", content: [{ type: "output_text", text: "done", annotations: [] }] } },
      completed,
    ]);
  });
}).listen(port, "127.0.0.1", () => console.log(`[mock] listening ${port}`));
```

